import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  renameSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { canonicalDirectory, describeEntry, inspectManagedPath } from "./path-policy.mjs";

/**
 * Keep the canonical root MIT notice beside each installed skill. The root
 * notice is the only source; skill-level notices are generated bytes.
 */
export function syncNotices({
  root,
  checkOnly = false,
  readFile = readFileSync,
  writeFile = writeFileSync,
  renameFile = renameSync,
  removeFile = rmSync,
} = {}) {
  const problems = [];
  const operations = [];
  const rootCheck = canonicalDirectory(root, "repository root");
  if (!rootCheck.ok) return { problems: [rootCheck.error], operations, skillCount: 0, synced: 0 };

  const repoRoot = rootCheck.path;
  const licensePath = join(repoRoot, "LICENSE");
  const licenseCheck = inspectManagedPath(repoRoot, licensePath, {
    label: "LICENSE",
    kind: "file",
  });
  if (!licenseCheck.ok) return { problems: [licenseCheck.error], operations, skillCount: 0, synced: 0 };

  const skillsRoot = join(repoRoot, "skills");
  const skillsCheck = inspectManagedPath(repoRoot, skillsRoot, {
    label: "skills/",
    kind: "directory",
  });
  if (!skillsCheck.ok) return { problems: [skillsCheck.error], operations, skillCount: 0, synced: 0 };

  const skillNames = [];
  for (const entry of readdirSync(skillsRoot, { withFileTypes: true })) {
    if (entry.name === "references" || entry.name.startsWith(".")) continue;
    const described = describeEntry(skillsRoot, entry);
    if (described.kind === "link") {
      problems.push(`skills/${entry.name}: skill directory must not be a symbolic link or junction`);
      continue;
    }
    if (described.kind !== "directory") continue;
    skillNames.push(entry.name);
  }
  skillNames.sort();

  const expected = readFile(licensePath);

  for (const skillName of skillNames) {
    const targetPath = join(skillsRoot, skillName, "LICENSE");
    const display = `skills/${skillName}/LICENSE`;
    let actual = null;

    if (existsSync(targetPath)) {
      const check = inspectManagedPath(repoRoot, targetPath, { label: display, kind: "file" });
      if (!check.ok) {
        problems.push(check.error);
        continue;
      }
      actual = readFile(targetPath);
    }

    if (actual && Buffer.from(actual).equals(Buffer.from(expected))) continue;

    if (checkOnly) {
      problems.push(`${display}: missing or out of date`);
    } else {
      operations.push({ display, targetPath, bytes: expected });
    }
  }

  if (problems.length > 0 || checkOnly) {
    return { problems, operations, skillCount: skillNames.length, synced: 0 };
  }

  let synced = 0;
  for (const operation of operations) {
    const targetCheck = inspectManagedPath(repoRoot, operation.targetPath, {
      label: operation.display,
      kind: "file",
      allowMissing: true,
    });
    if (!targetCheck.ok) {
      problems.push(targetCheck.error);
      break;
    }

    const temporaryPath = `${operation.targetPath}.tmp-${process.pid}`;
    try {
      writeFile(temporaryPath, operation.bytes);
      renameFile(temporaryPath, operation.targetPath);
      synced += 1;
    } catch (error) {
      try {
        removeFile(temporaryPath, { force: true });
      } catch {
        // Best-effort cleanup; the write diagnostic is more useful.
      }
      problems.push(`${operation.display}: write failed (${error.code ?? error.message})`);
      break;
    }
  }

  return { problems, operations, skillCount: skillNames.length, synced };
}

export function ensureDirectory(path) {
  mkdirSync(path, { recursive: true });
}
